"""Host-ready visual record of paired rigid rotation and material-resolution trials."""
from pathlib import Path
import sys,json,shutil
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from PIL import Image,ImageDraw,ImageFont
root=Path(sys.argv[1]);target=Path(sys.argv[2]);target.mkdir(parents=True,exist_ok=True);assets=target/'assets';assets.mkdir(exist_ok=True)
summary=json.loads((root/'comparison.json').read_text());mapping=json.loads((root/'render-map.json').read_text())
labels={'detailed-64m':'64 m detailed reference','rotating-64m':'64 m rotating approximation','translating-64m':'64 m translating approximation','detailed-32m':'32 m subdivision trial'}
series={b:[] for b in labels}
for row in mapping:
 b=row['branch'];i=row['render-index'];d=json.loads((root/b/row['source']).read_text());paths={}
 for view in ['composition','raw','resolution']:
  src=root/'native'/f'{view}-{i:04d}.png';dst=assets/f'{b}-{view}-{len(series[b]):03d}.png';shutil.copy2(src,dst);paths[view]='assets/'+dst.name
 series[b].append({'time':d['time-s']-3040.25,'images':paths,'cells':d['account']['material-cells'],'active':d['account']['physics-bodies']})
plt.style.use('dark_background');fig,axs=plt.subplots(1,2,figsize=(12,4),layout='constrained')
colors={'rotating-64m':'#76e6bf','translating-64m':'#a0b5ff','detailed-32m':'#ffb378'}
for b,color in colors.items():
 c=summary['curves'][b];axs[0].plot(c['time'],c['rms'],label=labels[b],color=color);axs[1].plot(c['time'],c['max'],label=labels[b],color=color)
axs[0].set_ylabel('Mass-weighted position RMS / m');axs[1].set_ylabel('Largest cell / parent-COM difference / m')
for ax in axs:ax.set_xlabel('Elapsed simulated seconds');ax.grid(alpha=.15)
axs[0].legend(fontsize=8);fig.savefig(assets/'errors.png',dpi=150);plt.close(fig)
# Exact-state side-by-side animation, with one image from each paired branch.
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',18)
frames=[]
for j in range(13):
 im=Image.new('RGB',(1280,690),(8,16,25));draw=ImageDraw.Draw(im)
 for k,b in enumerate(labels):
  p=target/series[b][j]['images']['composition'];thumb=Image.open(p).convert('RGB').crop((180,205,1080,660)).resize((640,324),Image.Resampling.LANCZOS)
  x=(k%2)*640;y=(k//2)*345;im.paste(thumb,(x,y+21));draw.text((x+14,y),labels[b]+f' / {j*10} s',font=font,fill='#d5eee9')
 frames.append(im)
frames[0].save(root/'rotation-comparison.gif',save_all=True,append_images=frames[1:],duration=220,loop=0)
rows=''.join(f"<tr><td>{labels[b]}</td><td>{m['active-bodies']}</td><td>{m['final-rms-position-error-m']:.2f} m</td><td>{m['final-max-position-error-m']:.2f} m</td></tr>" for b,m in summary['branches'].items())
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Truth · Spin and resolution</title><style>:root{color-scheme:dark;font:17px/1.6 system-ui;background:#081019;color:#dcecf1}body{max-width:1120px;margin:auto;padding:28px 20px 64px}a{color:#8ee2ca}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:14px;margin-bottom:48px}.eyebrow{letter-spacing:.14em;font-size:12px;color:#87d7bd}h1{font-size:clamp(38px,6vw,62px);line-height:1.08;letter-spacing:-.03em}h2{margin-top:46px;font-size:28px}p{max-width:880px;color:#b6cbd7}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}button,select{background:#172c37;color:#e3f8f0;border:1px solid #436474;padding:10px 13px;border-radius:7px;cursor:pointer}#screen{display:block;width:100%;border:1px solid #304b58;border-radius:12px}input{width:100%;accent-color:#8cdec2}#status{color:#86e4c0;margin:12px 0}.note{padding:22px;border-left:3px solid #ffb378;background:#17252c;border-radius:6px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #304754;padding:12px}.plot{width:100%;margin:20px 0}footer{color:#829eac;margin-top:48px;font-size:13px}</style></head><body><nav><a href="../">← Planetary Lab</a><a href="../adaptive/">Adaptive cycle</a><a href="../nebula/">Nebula</a></nav><div class="eyebrow">EXPERIMENT 04 · 24 OCTOBER 2026</div><h1>Let the coarse body spin.<br>Then test where it fails.</h1><p>The same assembled material receives a declared rotation perturbation of 0.0002 rad/s. Four continuations compare ordinary detailed cells, a rotating coarse aggregate, a translating aggregate, and eight-way subdivision into finer cells.</p><div class="controls"><select id="branch" aria-label="Physical model">BRANCH_OPTIONS</select><select id="view" aria-label="Render view"><option value="composition">Smooth material</option><option value="raw">Raw material cells</option><option value="resolution">Active / cached cells</option></select><button id="play">Play</button><button id="end">Compare at 120 s</button></div><div id="status" aria-live="polite"></div><img id="screen" alt="Actual native Truth simulation capture"><input id="seek" type="range" min="0" max="12" value="0" aria-label="Elapsed simulation frame"><p>Switch models without changing elapsed time. These are recorded native states. Surface extraction uses a 6 m display grid; physical target cell sizes are 64 m or 32 m.</p><h2>The rotating approximation helps on average.</h2><p>At 120 s, its position RMS difference from the detailed reference is <strong>3.26 m</strong>, compared with <strong>3.96 m</strong> for translation alone. The worst cell difference is slightly larger: 18.68 m versus 18.31 m. Rotation alone does not resolve internal deformation.</p><table><thead><tr><th>Continuation</th><th>Active bodies</th><th>RMS difference</th><th>Maximum difference</th></tr></thead><tbody>TABLE_ROWS</tbody></table><img class="plot" src="assets/errors.png" alt="Position RMS and maximum errors compared across the 120-second continuations"><h2>Finer cells exposed a mechanical mismatch.</h2><div class="note"><p>Splitting the already packed 84-cell body into 672 cells retained mass, material stocks and momentum, but changed the contact geometry. The new discrete state starts with <strong>4.30 GJ more modeled mechanical energy</strong>. Its later disagreement is therefore not a clean accuracy comparison.</p><p>This is a resolution-sensitivity trial, not validated adaptive refinement. A finer initial-cloud run tests assembly without imposing that subdivision on an already contacting aggregate.</p></div><h2>What this result establishes</h2><p>The coarse state now carries fixed world angular momentum and evolves orientation with the torque-free rigid-body equations. Residual non-rigid motion remains unresolved. Positions and velocities return to the same ECS at reactivation.</p><p>These forced shadow branches run for 120 s to reveal approximation error, beyond the normal time/displacement guards. This does not authorize longer automatic coarse intervals. The chemistry is still finite SiO₂, Fe and H₂O carriers; no reaction network or Primordia exchange was added.</p><footer>34 focused tests / 131 assertions passed. Full strict static analysis remains unavailable in this workspace. <a href="comparison.json">Inspect measured comparison</a>.</footer><script>const data=SERIES_DATA;let index=0,playing=false,timer;const $=id=>document.getElementById(id);function show(){const name=$('branch').value,f=data[name][index];$('screen').src=f.images[$('view').value];$('seek').value=index;$('status').textContent=`${f.time.toFixed(1)} s elapsed · ${f.active} active bodies · ${f.cells} retained material cells`}function loop(){if(!playing)return;index=(index+1)%13;show();timer=setTimeout(loop,350)}$('branch').onchange=show;$('view').onchange=show;$('seek').oninput=e=>{index=+e.target.value;show()};$('end').onclick=()=>{index=12;show()};$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play';clearTimeout(timer);if(playing)loop()};show();</script></body></html>'''
html=html.replace('TABLE_ROWS',rows).replace('BRANCH_OPTIONS',''.join(f'<option value="{k}">{v}</option>' for k,v in labels.items())).replace('SERIES_DATA',json.dumps(series,separators=(',',':')))
(target/'index.html').write_text(html);shutil.copy2(root/'comparison.json',target/'comparison.json')
print(json.dumps({'frames':len(mapping),'site-page':str(target/'index.html')},indent=2))
